// INBOX ファイルを username ごとにグループ化し、メンバー情報を付与

const result = $input.first().json;
if (!result.success || !result.files || result.files.length === 0) {
  // 空の場合: 空配列を返す → SplitInBatches が output[1]（done）を即発火
  return [];
}

// username → 日本語名 マッピング
const MEMBER_MAP = {
  miyawakiMM : { name: '宮脇', chatId: 'FILL_ME_CHAT_ID_miyawakiMM' },
  yoshioka   : { name: '吉岡', chatId: 'FILL_ME_CHAT_ID_yoshioka'   },
  kobayashi  : { name: '小林', chatId: 'FILL_ME_CHAT_ID_kobayashi'  },
  takada     : { name: '高田', chatId: 'FILL_ME_CHAT_ID_takada'     },
  kitashoji  : { name: '北庄司', chatId: 'FILL_ME_CHAT_ID_kitashoji' }
};

// username ごとにファイルをグループ化
const groups = {};
for (const file of result.files) {
  const u = file.username;
  if (!groups[u]) groups[u] = [];
  groups[u].push(file);
}

// メンバーごとの処理アイテムを生成
const items = [];
for (const [username, files] of Object.entries(groups)) {
  // prefix マッチ（yoshioka123 → yoshioka）
  let memberInfo = MEMBER_MAP[username];
  if (!memberInfo) {
    for (const [key, val] of Object.entries(MEMBER_MAP)) {
      if (username.startsWith(key)) { memberInfo = val; break; }
    }
  }
  if (!memberInfo) memberInfo = { name: username, chatId: '' };

  // 複数ファイルを時刻順に結合（YAMLフロントマターを除く）
  const combined = files
    .sort((a, b) => a.name.localeCompare(b.name))
    .map(f => f.content.replace(/^---[\s\S]*?---\s*/m, '').trim())
    .join('\n\n---\n\n');

  items.push({
    username,
    memberName   : memberInfo.name,
    chatId       : memberInfo.chatId,
    fileCount    : files.length,
    date         : result.date,
    combinedMemos: combined
  });
}

return items;

// SplitInBatches は $() で参照できないため、ここで現在アイテムを保持する
// 後続ノードから $('📎 ループ現在アイテム').first().json で参照可能
return $input.first().json;

// 前日タスク + 本日メモ を合成して Gemini へ渡すメッセージを作る
const pendingResult = $input.first().json;
const meta          = $('📎 ループ現在アイテム').first().json;

const pendingTasks = (pendingResult.content || '').trim();
const hasPending   = pendingTasks.length > 0;

let userMessage = '';
if (hasPending) {
  userMessage += `【前日未完了タスク】\n${pendingTasks}\n\n`;
}
userMessage += `【本日の音声メモ】\n${meta.combinedMemos}`;

return {
  ...meta,
  userMessage,
  hasPending
};

// Gemini レスポンスから日報テキストを取り出し、メタを引き継ぐ
const gemini = $input.first().json;
const meta   = $('📎 ループ現在アイテム').first().json;

const nippoText = gemini.candidates?.[0]?.content?.parts?.[0]?.text || '(日報生成失敗)';

return {
  username   : meta.username,
  memberName : meta.memberName,
  chatId     : meta.chatId,
  date       : meta.date,
  fileCount  : meta.fileCount,
  nippoText
};

// 生成済み日報からタスクを抽出して pending_tasks.md 用コンテンツを作成
const item = $input.first().json;
const text = item.nippoText || '';

const pendingLines = [];

// 前日継続タスクの未完了分
const contMatch = text.match(/## 前日からの継続タスク[\s\S]*?(?=\n## |\n# |$)/);
if (contMatch) {
  for (const line of contMatch[0].split('\n')) {
    if (/^- \[ \]/.test(line.trim())) pendingLines.push(line.trim());
  }
}

// 本日発生タスク
const newMatch = text.match(/## 本日発生タスク・アクション[\s\S]*?(?=\n## |\n# |$)/);
if (newMatch) {
  for (const line of newMatch[0].split('\n')) {
    if (/^- \[ \]/.test(line.trim())) pendingLines.push(line.trim());
  }
}

return {
  ...item,
  pendingTasksContent: pendingLines.join('\n')
};

// 本人への返信テキストを生成（ループの最後に実行）
const meta       = $('📋 日報テキスト整理').first().json;
const wikiResult = $('💾 Wiki保存 (GAS)').first().json;

const saved = wikiResult.success
  ? `📄 \`${wikiResult.path}\``
  : `⚠️ 保存失敗: ${wikiResult.error}`;

return {
  chatId     : meta.chatId,
  memberName : meta.memberName,
  date       : meta.date,
  nippoText  : meta.nippoText,
  fileCount  : meta.fileCount,
  savedPath  : wikiResult.path || '',
  replyText  : `📝 *${meta.date} 日報*\n${saved}\n\n${meta.nippoText}`
};

// 全メンバーの日報をまとめて宮脇さん向けサマリーを作成
// SplitInBatches の output[1]（done）から呼ばれる
// $('✉️ DM テキスト生成').all() で全ループ分のデータを集約

let allItems;
try {
  allItems = $('✉️ DM テキスト生成').all();
} catch(e) {
  allItems = [];
}

if (allItems.length === 0) {
  return {
    chatId: 'FILL_ME_CHAT_ID_miyawakiMM',
    text  : '📭 本日の日報はありませんでした。'
  };
}

const date = allItems[0].json.date || '';
let summary = `📊 *${date} 全員日報サマリー*\n`;
summary += `提出: ${allItems.length}名\n\n`;

for (const item of allItems) {
  const d = item.json;
  summary += `━━━━━━━━━━\n`;
  summary += `👤 *${d.memberName}*（${d.fileCount}件の音声メモ）\n`;
  summary += `📄 \`${d.savedPath}\`\n\n`;
  const preview = (d.nippoText || '').length > 300
    ? (d.nippoText || '').substring(0, 300) + '...'
    : (d.nippoText || '');
  summary += preview + '\n\n';
}

return {
  chatId: 'FILL_ME_CHAT_ID_miyawakiMM',
  text  : summary
};
